fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left ++ right == a (preserves order)
    // - if n > 1, then 0 < split < n so both parts are strictly shorter than a
    let split = if n <= 1 { n } else { n / 2 }; // for n>=2, n/2 is in [1, n-1]

    let left = a[..split].to_vec();
    let right = a[split..].to_vec();
    (left, right)
}